/// Estados possíveis do pedido simulado.
create static entity StatusPedido public (
  Id Integer identifier required,
  Label Text(50) required,
  Order Integer required
)
values
  Recebido (Id = 1, Label = "Recebido", Order = 1),
  EmSeparacao (Id = 2, Label = "EmSeparacao", Order = 2),
  Concluido (Id = 3, Label = "Concluido", Order = 3),
  Cancelado (Id = 4, Label = "Cancelado", Order = 4);

/// Agrupa produtos do catálogo.
create entity Categoria public label Nome (
  Id Long Integer identifier auto required,
  /// Nome exibido ao usuário.
  Nome Text(100) required,
  /// Dados de Ativa para a FarmaVirtual.
  Ativa Boolean default True
);

/// Produto comercializado na farmácia virtual.
create entity Produto public label Nome (
  Id Long Integer identifier auto required,
  /// Dados de CategoriaId para a FarmaVirtual.
  CategoriaId Categoria Identifier required references Categoria on delete Protect,
  /// Nome exibido ao usuário.
  Nome Text(200) required,
  /// Dados de Descricao para a FarmaVirtual.
  Descricao Text(2000),
  /// Dados de ImagemUrl para a FarmaVirtual.
  ImagemUrl Text(2048),
  /// Preço atual de venda.
  Preco Decimal(18,2),
  /// Dados de Estoque para a FarmaVirtual.
  Estoque Integer,
  /// Dados de Destaque para a FarmaVirtual.
  Destaque Boolean,
  /// Dados de Ativo para a FarmaVirtual.
  Ativo Boolean default True
);

/// Um produto por usuário no carrinho.
create entity CarrinhoItem public (
  Id Long Integer identifier auto required,
  /// Dados de UserId para a FarmaVirtual.
  UserId User Identifier required references User on delete Delete,
  /// Dados de ProdutoId para a FarmaVirtual.
  ProdutoId Produto Identifier required references Produto on delete Protect,
  /// Dados de Quantidade para a FarmaVirtual.
  Quantidade Integer required default 1
);
create unique index UQ_CarrinhoItem_UserProduto on CarrinhoItem (UserId, ProdutoId);

/// Cabeçalho da compra simulada com dados de entrega.
create entity Pedido public (
  Id Long Integer identifier auto required,
  /// Dados de UserId para a FarmaVirtual.
  UserId User Identifier required references User on delete Protect,
  /// Dados de StatusPedidoId para a FarmaVirtual.
  StatusPedidoId StatusPedido Identifier required references StatusPedido on delete Protect default Entities.StatusPedido.Recebido,
  /// Dados de CriadoEm para a FarmaVirtual.
  CriadoEm Date Time required default CurrDateTime(),
  /// Dados de Total para a FarmaVirtual.
  Total Decimal(18,2),
  /// Dados de NomeDestinatario para a FarmaVirtual.
  NomeDestinatario Text(200) required,
  /// Dados de EnderecoEntrega para a FarmaVirtual.
  EnderecoEntrega Text(1000) required,
  /// Dados de Observacao para a FarmaVirtual.
  Observacao Text(2000)
);

/// Guarda nome e preço históricos, independentes de mudanças no produto.
create entity PedidoItem public (
  Id Long Integer identifier auto required,
  /// Dados de PedidoId para a FarmaVirtual.
  PedidoId Pedido Identifier required references Pedido on delete Delete,
  /// Dados de ProdutoId para a FarmaVirtual.
  ProdutoId Produto Identifier required references Produto on delete Protect,
  /// Nome registrado na compra simulada.
  NomeProduto Text(200) required,
  /// Dados de Quantidade para a FarmaVirtual.
  Quantidade Integer required,
  /// Preço unitário registrado na compra simulada.
  PrecoUnitario Decimal(18,2),
  /// Valor dos itens calculado na compra simulada.
  Subtotal Decimal(18,2)
);

/// Critérios de pesquisa no catálogo.
type FiltroCatalogo public = {
  /// Dados de Busca para a FarmaVirtual.
  Busca: Text(200);
  /// Dados de CategoriaId para a FarmaVirtual.
  CategoriaId: Categoria Identifier;
  /// Dados de ApenasDisponiveis para a FarmaVirtual.
  ApenasDisponiveis: Boolean;
}

/// Dados do produto e valores calculados para exibir o carrinho.
type ItemCarrinhoDetalhe public = {
  /// Dados de CarrinhoItemId para a FarmaVirtual.
  CarrinhoItemId: CarrinhoItem Identifier;
  /// Dados de ProdutoId para a FarmaVirtual.
  ProdutoId: Produto Identifier;
  /// Nome exibido ao usuário.
  Nome: Text(200);
  /// Dados de ImagemUrl para a FarmaVirtual.
  ImagemUrl: Text(2048);
  /// Dados de Quantidade para a FarmaVirtual.
  Quantidade: Integer;
  /// Preço unitário registrado na compra simulada.
  PrecoUnitario: Decimal(18,2);
  /// Valor dos itens calculado na compra simulada.
  Subtotal: Decimal(18,2);
  /// Dados de EstoqueDisponivel para a FarmaVirtual.
  EstoqueDisponivel: Integer;
}

/// Itens e totais de um carrinho.
type ResumoCarrinho public = {
  /// Dados de Itens para a FarmaVirtual.
  Itens: ItemCarrinhoDetalhe List;
  /// Dados de QuantidadeTotal para a FarmaVirtual.
  QuantidadeTotal: Integer;
  /// Dados de Total para a FarmaVirtual.
  Total: Decimal(18,2);
}

/// Informações fornecidas para entregar o pedido.
type DadosEntrega public = {
  /// Dados de NomeDestinatario para a FarmaVirtual.
  NomeDestinatario: Text(200);
  /// Dados de EnderecoEntrega para a FarmaVirtual.
  EnderecoEntrega: Text(1000);
  /// Dados de Observacao para a FarmaVirtual.
  Observacao: Text(2000);
}
